struct Price: View {
    @Environment(\.locale) var locale
    var body: some View {
        Text(locale.identifier)
    }
}

struct Card: View {
    @Environment(\.dynamicTypeSize) var size
    var body: some View {
        Text(size >= .xxxLarge ? "Big" : "Normal")
    }
}

struct Arrow: View {
    @Environment(\.layoutDirection) var dir
    var body: some View {
        Text(dir == .rightToLeft ? "RTL" : "LTR")
    }
}

